VALUES (101, 'tt0110413', NULL, 'Léon: The Professional', 'Léon', 'movie', 1994, 'https://image.tmdb.org/t/p/w500/bxB2q91nKYp8JNzqE7t7TWBVupB.jpg', 'https://image.tmdb.org/t/p/original/fj0hwDJEOOHllRim2BMt5L7tbjf.jpg', 'Léon, the top hit man in New York, has earned a rep as an effective "cleaner". But when his next-door neighbors are wiped out by a loose-cannon DEA agent, he becomes the unwilling custodian of 12-year-old Mathilda. Before long, Mathilda''s thoughts turn to revenge, and she considers following in Léon''s footsteps.', NULL, NULL, 22.1232, 8.29, 0, 30.45, '2026-07-15 12:01:52', '2026-11-25 02:42:45')
