VALUES (2757, 'tt0268126', NULL, 'Adaptation.', 'Adaptation.', 'movie', 2002, 'https://image.tmdb.org/t/p/w500/ffEmHQAiD0m5dEQ6rlsuA9vlllW.jpg', 'https://image.tmdb.org/t/p/original/mkjdussWOjts0Se6hEwfTQdwCv2.jpg', 'Charlie Kaufman is a confused L.A. screenwriter overwhelmed by feelings of inadequacy, sexual frustration, self-loathing, and by the screenwriting ambitions of his freeloading twin brother Donald. While struggling to adapt "The Orchid Thief," by Susan Orlean, Kaufman''s life spins from pathetic to bizarre. The lives of Kaufman and Orlean''s book become strangely intertwined as each one''s search for passion collides with the other''s.', NULL, NULL, 5.1596, 7.324, 0, 21.459375, '2026-07-20 01:02:04', '2026-11-25 02:42:45')
