VALUES (4108, 'tt0293662', NULL, 'The Transporter', 'The Transporter', 'movie', 2002, 'https://image.tmdb.org/t/p/w500/dncJ81z1BahrT3ogLvlxOUC5n4u.jpg', 'https://image.tmdb.org/t/p/original/8dXR9R0NUo4eyS4hnYOsCywmo16.jpg', 'Former Special Forces officer Frank Martin will deliver anything to anyone for the right price, and his no-questions-asked policy puts him in high demand. But when he realizes his latest cargo is alive, it sets in motion a dangerous chain of events. The bound and gagged Lai is being smuggled to France by a shady American businessman, and Frank works to save her as his own illegal activities are uncovered by a French detective.', NULL, NULL, 8.8753, 6.732, 0, 1.34066666666666662e+01, '2026-07-20 01:02:04', '2026-11-25 02:42:45')
