VALUES (13555, 'tt0082427', NULL, 'The Funhouse', 'The Funhouse', 'movie', 1981, 'https://image.tmdb.org/t/p/w500/m3veWDvFIv3Y8QCYDHpOsM0OMkq.jpg', 'https://image.tmdb.org/t/p/original/uDIZFlKa3h9ufzxpGXerCbIgmLc.jpg', 'Rebellious teen Amy defies her parents by going to a trashy carnival that has pulled into town. In tow are her boyfriend, Buzz, and their friends Liz  and Richie. Thinking it would be fun to spend the night in the campy "Funhouse" horror ride, the teens witness a murder by a deformed worker wearing a mask. Locked in, Amy and her friends must evade the murderous carnival workers and escape before it leaves town the next day.', NULL, NULL, 1.9212, 5.8, 0, 1.60781818181818181e+01, '2026-07-20 04:02:06', '2026-11-25 02:42:45')
