VALUES (2059, 'tt0368891', NULL, 'National Treasure', 'National Treasure', 'movie', 2004, 'https://image.tmdb.org/t/p/w500/jKbZBMRFpF2EfFuvrsDZ2uQYsEQ.jpg', 'https://image.tmdb.org/t/p/original/9EnZD3ZWjpJy4IPoQkqTzxvZrso.jpg', 'Modern treasure hunters, led by archaeologist Ben Gates, search for a chest of riches rumored to have been stashed away by George Washington, Thomas Jefferson and Benjamin Franklin during the Revolutionary War. The chest''s whereabouts may lie in secret clues embedded in the Constitution and the Declaration of Independence, and Gates is in a race to find the gold before his enemies do.', NULL, NULL, 12.2489, 6.656, 0, 15.629, '2026-07-21 03:32:24', '2026-11-25 02:42:45')
