VALUES (569094, 'tt9362722', NULL, 'Spider-Man: Across the Spider-Verse', 'Spider-Man: Across the Spider-Verse', 'movie', 2023, 'https://image.tmdb.org/t/p/w500/8Vt6mWEReuy4Of61Lnj5Xj704m8.jpg', 'https://image.tmdb.org/t/p/original/kVd3a9YeLGkoeR50jGEXM6EqseS.jpg', 'After reuniting with Gwen Stacy, Brooklyn’s full-time, friendly neighborhood Spider-Man is catapulted across the Multiverse, where he encounters the Spider Society, a team of Spider-People charged with protecting the Multiverse''s very existence. But when the heroes clash on how to handle a new threat, Miles finds himself pitted against the other Spiders and must set out on his own to save those he loves most.', NULL, NULL, 26.1683, 8.3, 0, 1.61319999999999978e+01, '2026-07-21 03:32:24', '2026-11-25 02:42:45')
