VALUES (50646, 'tt1570728', NULL, 'Crazy, Stupid, Love.', 'Crazy, Stupid, Love.', 'movie', 2011, 'https://image.tmdb.org/t/p/w500/p4RafgAPk558muOjnBMHhMArjS2.jpg', 'https://image.tmdb.org/t/p/original/vyrCniZsrXZAW08eECKIp1BMLPh.jpg', 'Cal Weaver is living the American dream. He has a good job, a beautiful house, great children and a beautiful wife, named Emily. Cal''s seemingly perfect life unravels, however, when he learns that Emily has been unfaithful and wants a divorce. Over 40 and suddenly single, Cal is adrift in the fickle world of dating. Enter, Jacob Palmer, a self-styled player who takes Cal under his wing and teaches him how to be a hit with the ladies.', NULL, NULL, 10.4525, 7.279, 0, 11.105, '2026-07-29 20:51:09', '2026-11-25 02:42:45')
